function TopicTags({ transcript }) {
  const topicMap = {
    "Nursing": ["nurs", "hospital", "clinical", "patient", "medical"],
    "Entrepreneurship": ["startup", "business", "entrepreneur", "build"],
    "Podcasts": ["podcast", "episode", "listen", "jay shetty"],
    "Tech": ["tech", "software", "app", "code", "computer"],
    "Family": ["mom", "dad", "parent", "family", "sister", "brother"],
    "School": ["class", "major", "study", "professor", "campus"],
    "Cooking": ["cook", "food", "eat", "restaurant", "meal"],
    "Music": ["music", "song", "artist", "album", "playlist"],
    "Sports": ["sport", "game", "team", "basketball", "football"],
  }
  const lower = transcript.toLowerCase()
  const detected = Object.entries(topicMap)
    .filter(([_, kws]) => kws.some(k => lower.includes(k)))
    .map(([topic]) => topic)

  if (!detected.length) return <span style={{ fontSize: 11, color: C.textMuted }}>None detected</span>

  return (
    <span>
      {detected.map(t => (
        <span key={t} style={{ fontSize: 11, color: C.teal, background: `${C.teal}10`, padding: "3px 10px", borderRadius: 10, border: `1px solid ${C.teal}25`, marginRight: 6, display: "inline-block", marginTop: 4 }}>{t}</span>
      ))}
    </span>
  )
}

